window.LESSON_DATA = {"schemaVersion":"1.0.0","version":"4.0.0","buildDate":"2026-08-03","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":1,"title":"Number and Algebra"},"lesson":{"number":"1.1","slug":"standard-form","title":"Scientific Notation and Orders of Magnitude","subtitle":"Represent very large and very small quantities efficiently, calculate with powers of ten, and interpret scale.","syllabus_focus":"SL 1.1 — Operations with numbers in the form a × 10^k, where 1 ≤ a < 10 and k is an integer.","skill_keys":["IBAI.U1.NUMBER","IBAI.U1.MODELING"],"objectives":["Convert fluently between ordinary notation and standard form.","Multiply, divide, add and subtract quantities written with powers of ten.","Use order of magnitude to compare scales and test the reasonableness of a result.","Communicate units, precision and interpretation in authentic scientific and social contexts.","Classify familiar real numbers and distinguish exact values from approximations.","Use unit powers correctly when converting length, area and volume.","Validate calculator output using order of magnitude and an independent estimate."],"vocab":["standard form","coefficient","power of ten","integer exponent","order of magnitude","scale","reasonable estimate","natural number","integer","rational number","irrational number","exact value","normalized form","guard digit"],"technology":"Use the calculator scientific-notation key, but read the display structurally: coefficient first, exponent second. Test a result with a one-significant-figure estimate.","transition":"This lesson remains central in both the current course and the first-assessment-2029 course.","source_basis":["Pearson — Number and algebra basics","Haese — Approximations and error","Nikolaidis — Numbers, rounding, scientific form and percentage error"]},"slides":[{"section":"Launch","title":"1.1 · Scientific Notation and Orders of Magnitude","html":"<div class=\"cover-grid\"><div><div class=\"cover-kicker\">IB DP Mathematics · Applications and Interpretation SL</div><h1><span class=\"cover-number\">1.1</span>Scientific Notation and Orders of Magnitude</h1><p class=\"cover-subtitle\">Represent very large and very small quantities efficiently, calculate with powers of ten, and interpret scale.</p><div class=\"pill-row\"><span>Current syllabus</span><span>Technology-rich</span><span>Modelling</span><span>Unified definitive lesson</span></div></div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"1.1 · Scientific Notation and Orders of Magnitude\">\n      <defs><filter id=\"v3shadow-1-1-1\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">1.1 · Scientific Notation and Orders of Magnitude</text>\n      <line x1=\"72\" y1=\"162\" x2=\"548\" y2=\"162\" stroke=\"#17324D\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n      <path d=\"M90 92 C210 72 405 72 530 92\" fill=\"none\" stroke=\"#D4A72C\" stroke-width=\"4\" stroke-dasharray=\"10 9\"/>\n      <g><circle cx=\"82\" cy=\"162\" r=\"11\" fill=\"#7A1733\" filter=\"url(#v3shadow-1-1-1)\"/>\n      <text x=\"82\" y=\"124\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">estimate</text></g><g><circle cx=\"196\" cy=\"162\" r=\"11\" fill=\"#17324D\" filter=\"url(#v3shadow-1-1-1)\"/>\n      <text x=\"196\" y=\"205\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">calculate</text></g><g><circle cx=\"310\" cy=\"162\" r=\"15\" fill=\"#177E89\" filter=\"url(#v3shadow-1-1-1)\"/>\n      <text x=\"310\" y=\"124\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">units</text></g><g><circle cx=\"424\" cy=\"162\" r=\"11\" fill=\"#D4A72C\" filter=\"url(#v3shadow-1-1-1)\"/>\n      <text x=\"424\" y=\"205\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">validate</text></g><g><circle cx=\"538\" cy=\"162\" r=\"11\" fill=\"#5D6A75\" filter=\"url(#v3shadow-1-1-1)\"/>\n      <text x=\"538\" y=\"124\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">estimate</text></g><text x=\"310\" y=\"255\" text-anchor=\"middle\" fill=\"#5D6A75\" font-size=\"13\">read scale · compare structure · interpret units</text>\n    </svg></div><div class=\"v3-release-badge\"><b>Definitive v4</b><span>61 learn slides · 52 practice questions · 14 quiz questions · 3 extended tasks</span></div>","kind":"cover","eyebrow":"Unit 1 · Number and Algebra"},{"section":"Launch","title":"Your place in Unit 1","html":"<div class=\"unit-map\"><div class=\"map-node active\"><b>1.1</b><span>Scientific Notation and Orders of Magnitude</span></div><div class=\"map-node \"><b>1.2</b><span>Arithmetic Sequences and Series</span></div><div class=\"map-node \"><b>1.3</b><span>Geometric Sequences and Series</span></div><div class=\"map-node \"><b>1.4</b><span>Financial Applications of Sequences</span></div><div class=\"map-node \"><b>1.5</b><span>Introduction to Logarithms</span></div><div class=\"map-node \"><b>1.6</b><span>Approximation, Bounds and Percentage Error</span></div><div class=\"map-node \"><b>1.7</b><span>Loans, Annuities and Amortization</span></div><div class=\"map-node \"><b>1.8</b><span>Technology for Equations and Systems</span></div></div><p class=\"callout\">The course moves from representation and discrete change to financial modelling, uncertainty and technology-based solution methods.</p>","kind":"content","eyebrow":""},{"section":"Launch","title":"Syllabus focus","html":"<div class=\"focus-card\"><h3>Current course alignment</h3><p>SL 1.1 — Operations with numbers in the form a × 10^k, where 1 ≤ a < 10 and k is an integer.</p><p><b>Platform mastery keys:</b> IBAI.U1.NUMBER, IBAI.U1.MODELING</p></div><div class=\"transition-note\">This lesson remains central in both the current course and the first-assessment-2029 course.</div><div class=\"v3-source-basis\"><b>Reference basis</b><span>Pearson — Number and algebra basics</span><span>Haese — Approximations and error</span><span>Nikolaidis — Numbers, rounding, scientific form and percentage error</span></div>","kind":"content","eyebrow":""},{"section":"Inquiry","title":"A question worth investigating","html":"<blockquote>How can one compact notation make quantities from cells to galaxies comparable?</blockquote><p>Record an initial response. Return to it at the end and identify how your reasoning changed.</p><textarea class=\"student-note\" data-note=\"inquiry\" aria-label=\"Inquiry response\"></textarea>","kind":"inquiry","eyebrow":""},{"section":"Inquiry","title":"Learning intentions","html":"<div class=\"two-col\"><div><h3>By the end, you can…</h3><ul class=\"check-list\"><li>Convert fluently between ordinary notation and standard form.</li><li>Multiply, divide, add and subtract quantities written with powers of ten.</li><li>Use order of magnitude to compare scales and test the reasonableness of a result.</li><li>Communicate units, precision and interpretation in authentic scientific and social contexts.</li></ul></div><div><h3>Evidence of understanding</h3><ul class=\"check-list\"><li>Choose an efficient representation.</li><li>Use technology transparently.</li><li>Interpret rather than merely calculate.</li><li>Evaluate assumptions and precision.</li></ul></div></div>","kind":"content","eyebrow":""},{"section":"Diagnostic","title":"Prior-knowledge diagnostic","html":"<div class=\"student-turn\"><h3>Try before instruction</h3><p>Without a calculator, estimate \\(\\frac{6.2\\times10^7}{3.1\\times10^3}\\). Explain how the exponent predicts the scale of the answer.</p><textarea class=\"student-note\" data-note=\"diagnostic\"></textarea><details><summary>Diagnostic lens</summary><p>Focus on structure, units and the meaning of the result—not just a final number.</p></details></div>","kind":"student","eyebrow":""},{"section":"Language","title":"Core vocabulary","html":"<div class=\"vocab-grid\"><div class=\"vocab-chip\">standard form</div><div class=\"vocab-chip\">coefficient</div><div class=\"vocab-chip\">power of ten</div><div class=\"vocab-chip\">integer exponent</div><div class=\"vocab-chip\">order of magnitude</div><div class=\"vocab-chip\">scale</div><div class=\"vocab-chip\">reasonable estimate</div></div><p class=\"callout\">Use precise vocabulary in every explanation. In IB mathematics, communication earns meaning, not decoration.</p>","kind":"content","eyebrow":""},{"section":"Approach","title":"The AI modelling cycle","html":"<div class=\"cycle\"><div>Context</div><span>→</span><div>Assumptions</div><span>→</span><div>Mathematical form</div><span>→</span><div>Technology & computation</div><span>→</span><div>Interpretation</div><span>→</span><div>Validation & refinement</div></div><p>Every substantial task in this lesson returns to this cycle. A numerical answer without interpretation is unfinished.</p>","kind":"content","eyebrow":""},{"section":"Concept 1","title":"The normalized form","html":"<div class=\"concept-grid\"><div><p>A non-zero number is in standard form when it is written as \\(a\\times10^k\\), with \\(1\\le |a|<10\\) and integer \\(k\\). The coefficient records significant digits; the exponent records scale.</p><div class=\"formula-panel\">\\[N=a\\times10^k,\\qquad 1\\le |a|<10\\]</div></div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"The normalized form\">\n      <defs><filter id=\"v3shadow-1-1-2\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">The normalized form</text>\n      <circle cx=\"310\" cy=\"166\" r=\"94\" fill=\"#D4A72C\" opacity=\"0.11\" stroke=\"#D4A72C\" stroke-width=\"3\"/>\n      <text x=\"422\" y=\"146.5\" fill=\"#D4A72C\" font-size=\"13\" font-weight=\"800\">N</text><circle cx=\"310\" cy=\"166\" r=\"70\" fill=\"#177E89\" opacity=\"0.18\" stroke=\"#177E89\" stroke-width=\"3\"/>\n      <text x=\"398\" y=\"152.5\" fill=\"#177E89\" font-size=\"13\" font-weight=\"800\">Z</text><circle cx=\"310\" cy=\"166\" r=\"46\" fill=\"#17324D\" opacity=\"0.25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <text x=\"374\" y=\"158.5\" fill=\"#17324D\" font-size=\"13\" font-weight=\"800\">Q</text><circle cx=\"310\" cy=\"166\" r=\"23\" fill=\"#7A1733\" opacity=\"0.32\" stroke=\"#7A1733\" stroke-width=\"3\"/>\n      <text x=\"351\" y=\"164.25\" fill=\"#7A1733\" font-size=\"13\" font-weight=\"800\">R</text><circle cx=\"310\" cy=\"166\" r=\"8\" fill=\"#7A1733\"/>\n      <path d=\"M205 82 Q310 25 415 82\" fill=\"none\" stroke=\"#D4A72C\" stroke-width=\"4\" stroke-dasharray=\"9 8\"/>\n      <text x=\"310\" y=\"267\" text-anchor=\"middle\" fill=\"#5D6A75\" font-size=\"13\">nested ideas · inverse relationships · constraints</text>\n    </svg></div>","kind":"content","eyebrow":"Concept cycle 1 of 5"},{"section":"Concept 1","title":"Worked example · The normalized form","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Write \\(0.000438\\) in standard form.</p></div><div class=\"method\"><span>Reasoning</span><p>Move the decimal four places right: \\(0.000438=4.38\\times10^{-4}\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 1","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Write \\(72\\,900\\,000\\) in standard form.</p><textarea class=\"student-note\" data-note=\"turn-1\"></textarea><details><summary>Reveal answer and check</summary><p>\\(7.29\\times10^7\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 1","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(7.29\\times10^7\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 1","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>\\(72.9\\times10^6\\) has the correct value but is not normalized because the coefficient exceeds 10.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 2","title":"Moving between forms","html":"<div class=\"concept-grid\"><div><p>A positive exponent moves the decimal point right when expanding; a negative exponent moves it left. Keep zeros as place holders, not as new significant digits.</p><div class=\"formula-panel\">\\[3.06\\times10^{-5}=0.0000306\\]</div></div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"Moving between forms\">\n      <defs><filter id=\"v3shadow-1-1-3\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">Moving between forms</text>\n      <g><rect x=\"72\" y=\"222\" width=\"104\" height=\"40\" rx=\"13\" fill=\"#7A1733\" opacity=\"0.86\"/>\n        <text x=\"124\" y=\"246\" text-anchor=\"middle\" fill=\"white\" font-size=\"13\" font-weight=\"850\">0.000438</text></g><g><rect x=\"188\" y=\"182\" width=\"104\" height=\"54\" rx=\"13\" fill=\"#17324D\" opacity=\"0.89\"/>\n        <text x=\"240\" y=\"206\" text-anchor=\"middle\" fill=\"white\" font-size=\"13\" font-weight=\"850\">4.38 × 10⁻⁴</text></g><g><rect x=\"304\" y=\"142\" width=\"104\" height=\"68\" rx=\"13\" fill=\"#177E89\" opacity=\"0.9199999999999999\"/>\n        <text x=\"356\" y=\"166\" text-anchor=\"middle\" fill=\"white\" font-size=\"13\" font-weight=\"850\">a</text></g><g><rect x=\"420\" y=\"102\" width=\"104\" height=\"82\" rx=\"13\" fill=\"#D4A72C\" opacity=\"0.95\"/>\n        <text x=\"472\" y=\"126\" text-anchor=\"middle\" fill=\"white\" font-size=\"13\" font-weight=\"850\">k</text></g><path d=\"M87 248 C185 225 265 190 350 154 C430 120 486 106 548 88\" fill=\"none\" stroke=\"#17324D\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n      <polygon points=\"548,88 529,85 538,102\" fill=\"#17324D\"/>\n      <text x=\"310\" y=\"272\" text-anchor=\"middle\" fill=\"#5D6A75\" font-size=\"13\">each step must preserve the model rule</text>\n    </svg></div>","kind":"content","eyebrow":"Concept cycle 2 of 5"},{"section":"Concept 2","title":"Worked example · Moving between forms","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Expand \\(8.021\\times10^6\\).</p></div><div class=\"method\"><span>Reasoning</span><p>Move six places right: \\(8\\,021\\,000\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 2","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Expand \\(5.7\\times10^{-3}\\).</p><textarea class=\"student-note\" data-note=\"turn-2\"></textarea><details><summary>Reveal answer and check</summary><p>\\(0.0057\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 2","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(0.0057\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 2","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>The sign of the exponent describes scale, not the sign of the number.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 3","title":"Multiplication and division","html":"<div class=\"concept-grid\"><div><p>Operate on coefficients and powers separately, then renormalize. Exponents add under multiplication and subtract under division.</p><div class=\"formula-panel\">\\[(a\\times10^m)(b\\times10^n)=ab\\times10^{m+n}\\]</div></div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"Multiplication and division\">\n      <defs><filter id=\"v3shadow-1-1-4\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">Multiplication and division</text>\n      <g filter=\"url(#v3shadow-1-1-4)\"><rect x=\"70\" y=\"88\" width=\"220\" height=\"70\" rx=\"18\" fill=\"white\" stroke=\"#7A1733\" stroke-width=\"3\"/>\n      <circle cx=\"100\" cy=\"123\" r=\"14\" fill=\"#7A1733\"/><text x=\"126\" y=\"129\" fill=\"#17324D\" font-size=\"14\" font-weight=\"800\">coefficients</text></g><g filter=\"url(#v3shadow-1-1-4)\"><rect x=\"330\" y=\"88\" width=\"220\" height=\"70\" rx=\"18\" fill=\"white\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <circle cx=\"360\" cy=\"123\" r=\"14\" fill=\"#17324D\"/><text x=\"386\" y=\"129\" fill=\"#17324D\" font-size=\"14\" font-weight=\"800\">powers</text></g><g filter=\"url(#v3shadow-1-1-4)\"><rect x=\"70\" y=\"184\" width=\"220\" height=\"70\" rx=\"18\" fill=\"white\" stroke=\"#177E89\" stroke-width=\"3\"/>\n      <circle cx=\"100\" cy=\"219\" r=\"14\" fill=\"#177E89\"/><text x=\"126\" y=\"225\" fill=\"#17324D\" font-size=\"14\" font-weight=\"800\">normalize</text></g><g filter=\"url(#v3shadow-1-1-4)\"><rect x=\"330\" y=\"184\" width=\"220\" height=\"70\" rx=\"18\" fill=\"white\" stroke=\"#D4A72C\" stroke-width=\"3\"/>\n      <circle cx=\"360\" cy=\"219\" r=\"14\" fill=\"#D4A72C\"/><text x=\"386\" y=\"225\" fill=\"#17324D\" font-size=\"14\" font-weight=\"800\">interpret</text></g><path d=\"M290 123 L330 123 M290 219 L330 219\" stroke=\"#D4A72C\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n      <polygon points=\"330,123 317,116 317,130\" fill=\"#D4A72C\"/><polygon points=\"330,219 317,212 317,226\" fill=\"#D4A72C\"/>\n    </svg></div>","kind":"content","eyebrow":"Concept cycle 3 of 5"},{"section":"Concept 3","title":"Worked example · Multiplication and division","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Calculate \\((4.8\\times10^7)(2.5\\times10^{-3})\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\(4.8(2.5)\\times10^4=12\\times10^4=1.2\\times10^5\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 3","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Calculate \\(\\frac{9.6\\times10^{-4}}{3.2\\times10^2}\\).</p><textarea class=\"student-note\" data-note=\"turn-3\"></textarea><details><summary>Reveal answer and check</summary><p>\\(3\\times10^{-6}\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 3","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(3\\times10^{-6}\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 3","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Do not multiply exponents. The laws of indices determine how exponents combine.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 4","title":"Addition and subtraction","html":"<div class=\"concept-grid\"><div><p>Before adding or subtracting, rewrite quantities using a common power of ten. Only then combine coefficients.</p><div class=\"formula-panel\">\\[4.2\\times10^5+7.0\\times10^4=(4.2+0.70)\\times10^5\\]</div></div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"Addition and subtraction\">\n      <defs><filter id=\"v3shadow-1-1-5\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">Addition and subtraction</text>\n      <line x1=\"72\" y1=\"238\" x2=\"558\" y2=\"238\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <line x1=\"92\" y1=\"250\" x2=\"92\" y2=\"78\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M95 220 C165 207 205 196 258 166 C327 126 385 94 548 84\" fill=\"none\" stroke=\"#177E89\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <path d=\"M95 224 L205 190 L315 156 L425 122 L548 88\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"4\" stroke-dasharray=\"10 8\"/>\n      <g><circle cx=\"135\" cy=\"210\" r=\"8\" fill=\"#7A1733\"/><text x=\"135\" y=\"258\" text-anchor=\"middle\" fill=\"#17324D\" font-size=\"12\" font-weight=\"750\">km</text></g><g><circle cx=\"255\" cy=\"176\" r=\"8\" fill=\"#17324D\"/><text x=\"255\" y=\"104\" text-anchor=\"middle\" fill=\"#17324D\" font-size=\"12\" font-weight=\"750\">m</text></g><g><circle cx=\"375\" cy=\"142\" r=\"8\" fill=\"#177E89\"/><text x=\"375\" y=\"258\" text-anchor=\"middle\" fill=\"#17324D\" font-size=\"12\" font-weight=\"750\">km²</text></g><g><circle cx=\"495\" cy=\"108\" r=\"8\" fill=\"#D4A72C\"/><text x=\"495\" y=\"104\" text-anchor=\"middle\" fill=\"#17324D\" font-size=\"12\" font-weight=\"750\">m²</text></g>\n      <text x=\"535\" y=\"260\" fill=\"#5D6A75\" font-size=\"12\">index / time</text>\n    </svg></div>","kind":"content","eyebrow":"Concept cycle 4 of 5"},{"section":"Concept 4","title":"Worked example · Addition and subtraction","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Calculate \\(6.3\\times10^8-4.7\\times10^7\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\((6.3-0.47)\\times10^8=5.83\\times10^8\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 4","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Calculate \\(2.4\\times10^{-3}+8.0\\times10^{-4}\\).</p><textarea class=\"student-note\" data-note=\"turn-4\"></textarea><details><summary>Reveal answer and check</summary><p>\\(3.2\\times10^{-3}\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 4","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(3.2\\times10^{-3}\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 4","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Adding exponents is valid for multiplication, not for addition.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 5","title":"Order of magnitude and interpretation","html":"<div class=\"concept-grid\"><div><p>Order of magnitude compares scales approximately. After calculating, ask whether the coefficient, exponent and units make sense in context.</p><div class=\"formula-panel\">\\[\\text{order of magnitude}\\approx10^{\\operatorname{round}(\\log_{10}|N|)}\\]</div></div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"Order of magnitude and interpretation\">\n      <defs><filter id=\"v3shadow-1-1-6\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">Order of magnitude and interpretation</text>\n      <line x1=\"72\" y1=\"162\" x2=\"548\" y2=\"162\" stroke=\"#17324D\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n      <path d=\"M90 92 C210 72 405 72 530 92\" fill=\"none\" stroke=\"#D4A72C\" stroke-width=\"4\" stroke-dasharray=\"10 9\"/>\n      <g><circle cx=\"82\" cy=\"162\" r=\"11\" fill=\"#7A1733\" filter=\"url(#v3shadow-1-1-6)\"/>\n      <text x=\"82\" y=\"124\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">estimate</text></g><g><circle cx=\"196\" cy=\"162\" r=\"11\" fill=\"#17324D\" filter=\"url(#v3shadow-1-1-6)\"/>\n      <text x=\"196\" y=\"205\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">calculate</text></g><g><circle cx=\"310\" cy=\"162\" r=\"15\" fill=\"#177E89\" filter=\"url(#v3shadow-1-1-6)\"/>\n      <text x=\"310\" y=\"124\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">units</text></g><g><circle cx=\"424\" cy=\"162\" r=\"11\" fill=\"#D4A72C\" filter=\"url(#v3shadow-1-1-6)\"/>\n      <text x=\"424\" y=\"205\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">validate</text></g><g><circle cx=\"538\" cy=\"162\" r=\"11\" fill=\"#5D6A75\" filter=\"url(#v3shadow-1-1-6)\"/>\n      <text x=\"538\" y=\"124\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"750\" fill=\"#17324D\">estimate</text></g><text x=\"310\" y=\"255\" text-anchor=\"middle\" fill=\"#5D6A75\" font-size=\"13\">read scale · compare structure · interpret units</text>\n    </svg></div>","kind":"content","eyebrow":"Concept cycle 5 of 5"},{"section":"Concept 5","title":"Worked example · Order of magnitude and interpretation","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>A dataset has \\(3.2\\times10^6\\) rows of \\(2.5\\times10^2\\) bytes each. Estimate its size.</p></div><div class=\"method\"><span>Reasoning</span><p>\\(8.0\\times10^8\\) bytes, about \\(0.8\\) GB in decimal units.</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 5","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>A population grows from \\(4.0\\times10^5\\) to \\(1.2\\times10^6\\). By what factor did it grow?</p><textarea class=\"student-note\" data-note=\"turn-5\"></textarea><details><summary>Reveal answer and check</summary><p>A factor of \\(3\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 5","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>A factor of \\(3\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 5","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>An exponent difference of 2 means a factor of about \\(10^2=100\\), not a difference of 2.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Technology","title":"Interactive exploration","html":"<div id=\"lesson-lab\" class=\"lab\" data-lab=\"1.1\"></div><p class=\"lab-note\">Change more than one input. Predict before pressing calculate, then explain what stays invariant.</p>","kind":"lab","eyebrow":""},{"section":"Technology","title":"Transparent technology workflow","html":"<div class=\"workflow\"><div><b>1</b> Define variables and domain</div><div><b>2</b> Enter the mathematical model</div><div><b>3</b> Choose an appropriate tool</div><div><b>4</b> Record settings/output</div><div><b>5</b> Verify independently</div><div><b>6</b> Interpret and round</div></div><p>Use the calculator scientific-notation key, but read the display structurally: coefficient first, exponent second. Test a result with a one-significant-figure estimate.</p>","kind":"content","eyebrow":""},{"section":"Application","title":"Global and local context","html":"<div class=\"context-card\"><span>Context challenge</span><p>Estimate the number of litres of water used by a school community in one academic year, state assumptions, and express the result in standard form.</p></div><textarea class=\"student-note tall\" data-note=\"context\"></textarea>","kind":"student","eyebrow":""},{"section":"Inquiry","title":"Mini-investigation","html":"<div class=\"investigation\"><h3>Question → evidence → conclusion</h3><p>Choose a quantity spanning at least six orders of magnitude. Build a scale diagram, justify data choices, and explain one surprising comparison.</p><ul class=\"check-list\"><li>State the question and variables.</li><li>Record assumptions and data sources.</li><li>Show mathematics and technology output.</li><li>Interpret, evaluate and refine.</li></ul></div>","kind":"investigation","eyebrow":""},{"section":"Assessment","title":"IB command terms","html":"<div class=\"command-grid\"><div><b>Write down</b><span>Give the result with little or no working.</span></div><div><b>Calculate</b><span>Show enough method for the result to be reproducible.</span></div><div><b>Determine</b><span>Reach a result with supporting reasoning.</span></div><div><b>Explain</b><span>Give causes, mechanisms or mathematical meaning.</span></div><div><b>Interpret</b><span>Translate mathematics back into context.</span></div><div><b>Comment</b><span>Make a judgement supported by evidence.</span></div></div>","kind":"content","eyebrow":""},{"section":"Reference synthesis","title":"Number sets, exact values and approximations","kind":"content","eyebrow":"Source-informed deep dive 1 of 4","html":"<div class=\"concept-grid v3-reference-grid\"><div>\n          <div class=\"v3-reference-kicker\">Reference synthesis · original ECHS adaptation</div>\n          <p>Number sets describe algebraic structure; exact and approximate describe how a value is represented. A terminating or recurring decimal is rational, while constants such as π and √2 are irrational.</p>\n          <div class=\"formula-panel\">\\[\\mathbb{N}\\subset\\mathbb{Z}\\subset\\mathbb{Q}\\subset\\mathbb{R}\\]</div>\n          <div class=\"v3-source-strip\"><b>Built from:</b> Pearson — Number and algebra basics · Haese — Approximations and error · Nikolaidis — Numbers, rounding, scientific form and percentage error</div>\n        </div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"Number sets, exact values and approximations\">\n      <defs><filter id=\"v3shadow-1-1-7\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">Number sets, exact values and approximations</text>\n      <circle cx=\"310\" cy=\"166\" r=\"94\" fill=\"#D4A72C\" opacity=\"0.11\" stroke=\"#D4A72C\" stroke-width=\"3\"/>\n      <text x=\"422\" y=\"146.5\" fill=\"#D4A72C\" font-size=\"13\" font-weight=\"800\">N</text><circle cx=\"310\" cy=\"166\" r=\"70\" fill=\"#177E89\" opacity=\"0.18\" stroke=\"#177E89\" stroke-width=\"3\"/>\n      <text x=\"398\" y=\"152.5\" fill=\"#177E89\" font-size=\"13\" font-weight=\"800\">Z</text><circle cx=\"310\" cy=\"166\" r=\"46\" fill=\"#17324D\" opacity=\"0.25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <text x=\"374\" y=\"158.5\" fill=\"#17324D\" font-size=\"13\" font-weight=\"800\">Q</text><circle cx=\"310\" cy=\"166\" r=\"23\" fill=\"#7A1733\" opacity=\"0.32\" stroke=\"#7A1733\" stroke-width=\"3\"/>\n      <text x=\"351\" y=\"164.25\" fill=\"#7A1733\" font-size=\"13\" font-weight=\"800\">R</text><circle cx=\"310\" cy=\"166\" r=\"8\" fill=\"#7A1733\"/>\n      <path d=\"M205 82 Q310 25 415 82\" fill=\"none\" stroke=\"#D4A72C\" stroke-width=\"4\" stroke-dasharray=\"9 8\"/>\n      <text x=\"310\" y=\"267\" text-anchor=\"middle\" fill=\"#5D6A75\" font-size=\"13\">nested ideas · inverse relationships · constraints</text>\n    </svg></div>"},{"section":"Reference synthesis","title":"Worked example · Number sets, exact values and approximations","kind":"worked","eyebrow":"Model the reasoning, not only the result","html":"<div class=\"worked v3-worked\"><div class=\"prompt\"><span>Problem</span><p>Classify −7, 0.125 and √11 in the smallest familiar set and state whether each written value is exact.</p></div>\n          <div class=\"method\"><span>Complete reasoning</span><p>−7 is an integer; 0.125=1/8 is rational; √11 is irrational. Every displayed form is exact.</p></div></div>\n          <div class=\"v3-reasoning-ribbon\"><b>IB communication:</b> name the structure, show the governing rule, retain exact values where useful, then interpret.</div>"},{"section":"Reference synthesis","title":"Student transfer · Number sets, exact values and approximations","kind":"student","eyebrow":"Attempt before revealing","html":"<div class=\"student-turn v3-student-turn\"><h3>Transfer the idea</h3><p>Is 3.140 an exact value of π? Explain the role of the trailing zero.</p>\n          <textarea class=\"student-note\" data-note=\"v3-1.1-0\" aria-label=\"Student response\"></textarea>\n          <details><summary>Reveal a complete check</summary><p>3.140 is an exact terminating decimal but only an approximation to π. The zero communicates reported precision.</p></details>\n        </div><div class=\"misconception v3-misconception\"><div class=\"warning-symbol\">!</div><div><h3>Precision trap</h3><p>A long decimal is not automatically irrational; every terminating or recurring decimal is rational.</p></div></div>"},{"section":"Reference synthesis","title":"Normalized scientific notation","kind":"content","eyebrow":"Source-informed deep dive 2 of 4","html":"<div class=\"concept-grid v3-reference-grid\"><div>\n          <div class=\"v3-reference-kicker\">Reference synthesis · original ECHS adaptation</div>\n          <p>Scientific notation separates significant digits from scale. Normalization requires exactly one non-zero digit before the decimal point.</p>\n          <div class=\"formula-panel\">\\[N=a\\times10^k,\\qquad 1\\le |a|<10,\\quad k\\in\\mathbb{Z}\\]</div>\n          <div class=\"v3-source-strip\"><b>Built from:</b> Pearson — Number and algebra basics · Haese — Approximations and error · Nikolaidis — Numbers, rounding, scientific form and percentage error</div>\n        </div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"Normalized scientific notation\">\n      <defs><filter id=\"v3shadow-1-1-8\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">Normalized scientific notation</text>\n      <g><rect x=\"72\" y=\"222\" width=\"104\" height=\"40\" rx=\"13\" fill=\"#7A1733\" opacity=\"0.86\"/>\n        <text x=\"124\" y=\"246\" text-anchor=\"middle\" fill=\"white\" font-size=\"13\" font-weight=\"850\">0.000438</text></g><g><rect x=\"188\" y=\"182\" width=\"104\" height=\"54\" rx=\"13\" fill=\"#17324D\" opacity=\"0.89\"/>\n        <text x=\"240\" y=\"206\" text-anchor=\"middle\" fill=\"white\" font-size=\"13\" font-weight=\"850\">4.38 × 10⁻⁴</text></g><g><rect x=\"304\" y=\"142\" width=\"104\" height=\"68\" rx=\"13\" fill=\"#177E89\" opacity=\"0.9199999999999999\"/>\n        <text x=\"356\" y=\"166\" text-anchor=\"middle\" fill=\"white\" font-size=\"13\" font-weight=\"850\">a</text></g><g><rect x=\"420\" y=\"102\" width=\"104\" height=\"82\" rx=\"13\" fill=\"#D4A72C\" opacity=\"0.95\"/>\n        <text x=\"472\" y=\"126\" text-anchor=\"middle\" fill=\"white\" font-size=\"13\" font-weight=\"850\">k</text></g><path d=\"M87 248 C185 225 265 190 350 154 C430 120 486 106 548 88\" fill=\"none\" stroke=\"#17324D\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n      <polygon points=\"548,88 529,85 538,102\" fill=\"#17324D\"/>\n      <text x=\"310\" y=\"272\" text-anchor=\"middle\" fill=\"#5D6A75\" font-size=\"13\">each step must preserve the model rule</text>\n    </svg></div>"},{"section":"Reference synthesis","title":"Worked example · Normalized scientific notation","kind":"worked","eyebrow":"Model the reasoning, not only the result","html":"<div class=\"worked v3-worked\"><div class=\"prompt\"><span>Problem</span><p>Write 0.000438 and 72 900 000 in normalized scientific notation.</p></div>\n          <div class=\"method\"><span>Complete reasoning</span><p>0.000438=4.38×10^−4 and 72 900 000=7.29×10^7.</p></div></div>\n          <div class=\"v3-reasoning-ribbon\"><b>IB communication:</b> name the structure, show the governing rule, retain exact values where useful, then interpret.</div>"},{"section":"Reference synthesis","title":"Student transfer · Normalized scientific notation","kind":"student","eyebrow":"Attempt before revealing","html":"<div class=\"student-turn v3-student-turn\"><h3>Transfer the idea</h3><p>Write −0.00000604 in normalized form and identify a and k.</p>\n          <textarea class=\"student-note\" data-note=\"v3-1.1-1\" aria-label=\"Student response\"></textarea>\n          <details><summary>Reveal a complete check</summary><p>−6.04×10^−6, so a=−6.04 and k=−6.</p></details>\n        </div><div class=\"misconception v3-misconception\"><div class=\"warning-symbol\">!</div><div><h3>Precision trap</h3><p>72.9×10^6 has the right value but is not normalized because |72.9|≥10.</p></div></div>"},{"section":"Reference synthesis","title":"Operations and calculator notation","kind":"content","eyebrow":"Source-informed deep dive 3 of 4","html":"<div class=\"concept-grid v3-reference-grid\"><div>\n          <div class=\"v3-reference-kicker\">Reference synthesis · original ECHS adaptation</div>\n          <p>Multiplication and division combine coefficients and exponents separately. Addition and subtraction require a common power of ten first.</p>\n          <div class=\"formula-panel\">\\[(a\\times10^m)(b\\times10^n)=ab\\times10^{m+n}\\]</div>\n          <div class=\"v3-source-strip\"><b>Built from:</b> Pearson — Number and algebra basics · Haese — Approximations and error · Nikolaidis — Numbers, rounding, scientific form and percentage error</div>\n        </div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"Operations and calculator notation\">\n      <defs><filter id=\"v3shadow-1-1-9\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">Operations and calculator notation</text>\n      <g filter=\"url(#v3shadow-1-1-9)\"><rect x=\"70\" y=\"88\" width=\"220\" height=\"70\" rx=\"18\" fill=\"white\" stroke=\"#7A1733\" stroke-width=\"3\"/>\n      <circle cx=\"100\" cy=\"123\" r=\"14\" fill=\"#7A1733\"/><text x=\"126\" y=\"129\" fill=\"#17324D\" font-size=\"14\" font-weight=\"800\">coefficients</text></g><g filter=\"url(#v3shadow-1-1-9)\"><rect x=\"330\" y=\"88\" width=\"220\" height=\"70\" rx=\"18\" fill=\"white\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <circle cx=\"360\" cy=\"123\" r=\"14\" fill=\"#17324D\"/><text x=\"386\" y=\"129\" fill=\"#17324D\" font-size=\"14\" font-weight=\"800\">powers</text></g><g filter=\"url(#v3shadow-1-1-9)\"><rect x=\"70\" y=\"184\" width=\"220\" height=\"70\" rx=\"18\" fill=\"white\" stroke=\"#177E89\" stroke-width=\"3\"/>\n      <circle cx=\"100\" cy=\"219\" r=\"14\" fill=\"#177E89\"/><text x=\"126\" y=\"225\" fill=\"#17324D\" font-size=\"14\" font-weight=\"800\">normalize</text></g><g filter=\"url(#v3shadow-1-1-9)\"><rect x=\"330\" y=\"184\" width=\"220\" height=\"70\" rx=\"18\" fill=\"white\" stroke=\"#D4A72C\" stroke-width=\"3\"/>\n      <circle cx=\"360\" cy=\"219\" r=\"14\" fill=\"#D4A72C\"/><text x=\"386\" y=\"225\" fill=\"#17324D\" font-size=\"14\" font-weight=\"800\">interpret</text></g><path d=\"M290 123 L330 123 M290 219 L330 219\" stroke=\"#D4A72C\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n      <polygon points=\"330,123 317,116 317,130\" fill=\"#D4A72C\"/><polygon points=\"330,219 317,212 317,226\" fill=\"#D4A72C\"/>\n    </svg></div>"},{"section":"Reference synthesis","title":"Worked example · Operations and calculator notation","kind":"worked","eyebrow":"Model the reasoning, not only the result","html":"<div class=\"worked v3-worked\"><div class=\"prompt\"><span>Problem</span><p>Calculate (3.6×10^5)(2.5×10^−3), then normalize.</p></div>\n          <div class=\"method\"><span>Complete reasoning</span><p>The product is 9.0×10^2=900.</p></div></div>\n          <div class=\"v3-reasoning-ribbon\"><b>IB communication:</b> name the structure, show the governing rule, retain exact values where useful, then interpret.</div>"},{"section":"Reference synthesis","title":"Student transfer · Operations and calculator notation","kind":"student","eyebrow":"Attempt before revealing","html":"<div class=\"student-turn v3-student-turn\"><h3>Transfer the idea</h3><p>Calculate 4.2×10^7+6.8×10^6.</p>\n          <textarea class=\"student-note\" data-note=\"v3-1.1-2\" aria-label=\"Student response\"></textarea>\n          <details><summary>Reveal a complete check</summary><p>Rewrite 6.8×10^6=0.68×10^7, giving 4.88×10^7.</p></details>\n        </div><div class=\"misconception v3-misconception\"><div class=\"warning-symbol\">!</div><div><h3>Precision trap</h3><p>Exponents are not added when quantities are added; that rule belongs to multiplication.</p></div></div>"},{"section":"Reference synthesis","title":"Orders of magnitude, units and reasonableness","kind":"content","eyebrow":"Source-informed deep dive 4 of 4","html":"<div class=\"concept-grid v3-reference-grid\"><div>\n          <div class=\"v3-reference-kicker\">Reference synthesis · original ECHS adaptation</div>\n          <p>A nearest power-of-ten order of magnitude summarizes scale. Unit conversion must respect dimension: squaring or cubing a unit also squares or cubes its conversion factor.</p>\n          <div class=\"formula-panel\">\\[1\\text{ km}=10^3\\text{ m},\\quad1\\text{ km}^2=10^6\\text{ m}^2\\]</div>\n          <div class=\"v3-source-strip\"><b>Built from:</b> Pearson — Number and algebra basics · Haese — Approximations and error · Nikolaidis — Numbers, rounding, scientific form and percentage error</div>\n        </div><svg class=\"concept-visual v3-concept-visual\" viewBox=\"0 0 620 300\" role=\"img\" aria-label=\"Orders of magnitude, units and reasonableness\">\n      <defs><filter id=\"v3shadow-1-1-10\"><feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"10\" flood-opacity=\".12\"/></filter></defs>\n      <rect width=\"620\" height=\"300\" rx=\"28\" fill=\"#F8F4EE\"/>\n      <rect x=\"18\" y=\"18\" width=\"584\" height=\"264\" rx=\"24\" fill=\"#FFFDF9\" stroke=\"#DED7CE\"/>\n      <text x=\"42\" y=\"54\" font-size=\"18\" font-weight=\"850\" fill=\"#17324D\">Orders of magnitude, units and reasonableness</text>\n      <line x1=\"72\" y1=\"238\" x2=\"558\" y2=\"238\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <line x1=\"92\" y1=\"250\" x2=\"92\" y2=\"78\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M95 220 C165 207 205 196 258 166 C327 126 385 94 548 84\" fill=\"none\" stroke=\"#177E89\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <path d=\"M95 224 L205 190 L315 156 L425 122 L548 88\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"4\" stroke-dasharray=\"10 8\"/>\n      <g><circle cx=\"135\" cy=\"210\" r=\"8\" fill=\"#7A1733\"/><text x=\"135\" y=\"258\" text-anchor=\"middle\" fill=\"#17324D\" font-size=\"12\" font-weight=\"750\">km</text></g><g><circle cx=\"255\" cy=\"176\" r=\"8\" fill=\"#17324D\"/><text x=\"255\" y=\"104\" text-anchor=\"middle\" fill=\"#17324D\" font-size=\"12\" font-weight=\"750\">m</text></g><g><circle cx=\"375\" cy=\"142\" r=\"8\" fill=\"#177E89\"/><text x=\"375\" y=\"258\" text-anchor=\"middle\" fill=\"#17324D\" font-size=\"12\" font-weight=\"750\">km²</text></g><g><circle cx=\"495\" cy=\"108\" r=\"8\" fill=\"#D4A72C\"/><text x=\"495\" y=\"104\" text-anchor=\"middle\" fill=\"#17324D\" font-size=\"12\" font-weight=\"750\">m²</text></g>\n      <text x=\"535\" y=\"260\" fill=\"#5D6A75\" font-size=\"12\">index / time</text>\n    </svg></div>"},{"section":"Reference synthesis","title":"Worked example · Orders of magnitude, units and reasonableness","kind":"worked","eyebrow":"Model the reasoning, not only the result","html":"<div class=\"worked v3-worked\"><div class=\"prompt\"><span>Problem</span><p>Convert 4.82×10^−6 km² to m².</p></div>\n          <div class=\"method\"><span>Complete reasoning</span><p>4.82×10^−6×10^6=4.82 m².</p></div></div>\n          <div class=\"v3-reasoning-ribbon\"><b>IB communication:</b> name the structure, show the governing rule, retain exact values where useful, then interpret.</div>"},{"section":"Reference synthesis","title":"Student transfer · Orders of magnitude, units and reasonableness","kind":"student","eyebrow":"Attempt before revealing","html":"<div class=\"student-turn v3-student-turn\"><h3>Transfer the idea</h3><p>A file contains 7.5×10^9 bytes. Give its size in decimal gigabytes and its nearest power-of-ten order of magnitude.</p>\n          <textarea class=\"student-note\" data-note=\"v3-1.1-3\" aria-label=\"Student response\"></textarea>\n          <details><summary>Reveal a complete check</summary><p>7.5 GB; since 7.5×10^9 is closer to 10^10 than 10^9 on a logarithmic scale, its nearest order is 10^10 bytes.</p></details>\n        </div><div class=\"misconception v3-misconception\"><div class=\"warning-symbol\">!</div><div><h3>Precision trap</h3><p>For area, using 10^3 instead of 10^6 is a dimensional error, not merely a rounding error.</p></div></div>"},{"section":"Assessment","title":"Solar data archive","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 1-style short response</span><span>8 marks</span><span>GDC expected</span></div><h3>Solar data archive</h3><p>A satellite stores \\(3.6\\times10^5\\) images. Each image requires \\(2.4\\times10^6\\) bytes.</p><div class=\"task-part\"><b>(a)</b> Calculate the total storage in bytes, giving your answer in standard form. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(b)</b> A compression system reduces storage by 37%. Find the compressed storage in bytes in standard form. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(c)</b> The archive is copied at \\(1.5\\times10^8\\) bytes per second. Find the transfer time in minutes. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(d)</b> State one reason the calculated time may differ from real transfer time. <span class=\"marks\">[1]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"Solar data archive · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>Solar data archive — worked markscheme</h3><div class=\"solution-part\"><b>(a) \\(8.64\\times10^{11}\\) bytes</b><p>M1 multiplies the two quantities and applies exponent law; A1 normalized result.</p></div><div class=\"solution-part\"><b>(b) \\(5.4432\\times10^{11}\\) bytes</b><p>M1 uses multiplier 0.63; A1 correct value.</p></div><div class=\"solution-part\"><b>(c) \\(60.48\\) minutes</b><p>M1 divides storage by rate; A1 seconds \\(3628.8\\); A1 converts to minutes.</p></div><div class=\"solution-part\"><b>(d) Protocol overhead, variable transfer rate or interruptions.</b><p>A1 one relevant modelling limitation.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Assessment","title":"Water-use estimation","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 2-style extended response</span><span>10 marks</span><span>GDC expected</span></div><h3>Water-use estimation</h3><p>A campus has 1450 people. A preliminary model assumes each person uses \\(1.8\\times10^2\\) L of water per day on 210 operating days each year.</p><div class=\"task-part\"><b>(a)</b> Estimate annual water use in litres and write it in standard form. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(b)</b> Convert the answer to cubic metres, using \\(1\\text{ m}^3=10^3\\text{ L}\\). <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(c)</b> A conservation plan targets a 12% reduction. Calculate the target annual use in cubic metres. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(d)</b> Give two assumptions that should be tested before using the model for budgeting. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(e)</b> Explain why reporting the target to the nearest litre would be misleading. <span class=\"marks\">[1]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"Water-use estimation · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>Water-use estimation — worked markscheme</h3><div class=\"solution-part\"><b>(a) \\(5.481\\times10^7\\) L</b><p>M1 forms \\(1450(180)(210)\\); A1 evaluates; A1 standard form with units.</p></div><div class=\"solution-part\"><b>(b) \\(5.481\\times10^4\\text{ m}^3\\)</b><p>M1 divides by \\(10^3\\); A1 correct standard form.</p></div><div class=\"solution-part\"><b>(c) \\(48\\,232.8\\text{ m}^3\\)</b><p>M1 uses multiplier 0.88; A1 correct value.</p></div><div class=\"solution-part\"><b>(d) Examples: equal use per person; exactly 210 days; no leakage/irrigation variation; stable population.</b><p>A1 each for two distinct assumptions.</p></div><div class=\"solution-part\"><b>(e) The assumptions and input estimates do not justify that precision.</b><p>A1 links reporting precision to model uncertainty.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Connections","title":"Where this mathematics connects","html":"<div class=\"connection-grid\"><div>Measurement and uncertainty</div><div>Exponential models</div><div>Data storage and scientific scales</div><div>Fermi estimation</div></div><p>Write one sentence describing a connection you did not see at the start.</p><textarea class=\"student-note\" data-note=\"connection\"></textarea>","kind":"content","eyebrow":""},{"section":"Synthesis","title":"Five ideas to retain","html":"<ul class=\"check-list\"><li>The normalized form: A non-zero number is in standard form when it is written as \\(a\\times10^k\\), with \\(1\\le |a|<10\\) and integer \\(k\\).</li><li>Moving between forms: A positive exponent moves the decimal point right when expanding; a negative exponent moves it left.</li><li>Multiplication and division: Operate on coefficients and powers separately, then renormalize.</li><li>Addition and subtraction: Before adding or subtracting, rewrite quantities using a common power of ten.</li><li>Order of magnitude and interpretation: Order of magnitude compares scales approximately.</li></ul>","kind":"summary","eyebrow":""},{"section":"Reflection","title":"Return to the inquiry question","html":"<blockquote>How can one compact notation make quantities from cells to galaxies comparable?</blockquote><textarea class=\"student-note tall\" data-note=\"reflection\"></textarea><div class=\"reflection-grid\"><label><input type=\"checkbox\" data-reflect=\"model\"> I can model</label><label><input type=\"checkbox\" data-reflect=\"calculate\"> I can calculate</label><label><input type=\"checkbox\" data-reflect=\"interpret\"> I can interpret</label><label><input type=\"checkbox\" data-reflect=\"evaluate\"> I can evaluate</label></div>","kind":"reflection","eyebrow":""},{"section":"Exit","title":"Exit ticket","html":"<div class=\"exit-grid\"><div><b>One calculation</b><p>Create and solve a new example using today’s central formula.</p></div><div><b>One explanation</b><p>Describe a common error and how to detect it.</p></div><div><b>One evaluation</b><p>State one assumption that could change a conclusion.</p></div></div><textarea class=\"student-note tall\" data-note=\"exit\"></textarea>","kind":"student","eyebrow":""},{"section":"Next","title":"Practice Studio","html":"<div class=\"launch-panel\"><h2>40 original questions</h2><p>Four levels: Foundation, Application, Reasoning and Challenge. Every item includes marks, calculator guidance, hints and a complete solution.</p><button class=\"route-jump\" data-go=\"practice\">Open Practice Studio</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Independent timed quiz","html":"<div class=\"launch-panel\"><h2>10 fresh questions</h2><p>Complete the quiz under a suggested 25-minute timer, then review explanations and update your mastery reflection.</p><button class=\"route-jump\" data-go=\"quiz\">Start timed quiz</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Authenticated question-bank bridge","html":"<div class=\"bank-bridge\"><h2>More practice on the platform</h2><p>This lesson maps to <code>IBAI.U1.NUMBER, IBAI.U1.MODELING</code>. The attached private banks stay inside authenticated school access; no private prompt is copied into this public lesson file.</p><a href=\"https://2ed944-cloud.github.io/ECHS-Math/question-bank/practice.html?course=ib-math-ai&unit=1&lesson=1.1\" class=\"button-link\">Open additional bank practice</a></div>","kind":"launch","eyebrow":""}],"practice":[{"id":"IBAI-1.1-P01","level":"Foundation","prompt":"Write \\(0.000438\\) in standard form.","answer":"\\(4.38\\times10^{-4}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(-4\\), so the result is \\(4.38\\times10^{-4}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["4.38e-4","4.38*10^-4","4.38x10^-4"]}},{"id":"IBAI-1.1-P02","level":"Foundation","prompt":"Write \\(72900000\\) in standard form.","answer":"\\(7.29\\times10^{7}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(7\\), so the result is \\(7.29\\times10^{7}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["7.29e7","7.29*10^7","7.29x10^7"]}},{"id":"IBAI-1.1-P03","level":"Foundation","prompt":"Write \\(0.00602\\) in standard form.","answer":"\\(6.02\\times10^{-3}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(-3\\), so the result is \\(6.02\\times10^{-3}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["6.02e-3","6.02*10^-3","6.02x10^-3"]}},{"id":"IBAI-1.1-P04","level":"Foundation","prompt":"Write \\(905000000000\\) in standard form.","answer":"\\(9.05\\times10^{11}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(11\\), so the result is \\(9.05\\times10^{11}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["9.05e11","9.05*10^11","9.05x10^11"]}},{"id":"IBAI-1.1-P05","level":"Foundation","prompt":"Write \\(0.0000000817\\) in standard form.","answer":"\\(8.17\\times10^{-8}\\)","solution":"Move the decimal point until the coefficient is between 1 and 10. The movement gives exponent \\(-8\\), so the result is \\(8.17\\times10^{-8}\\).","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"text","accepted":["8.17e-8","8.17*10^-8","8.17x10^-8"]}},{"id":"IBAI-1.1-P06","level":"Foundation","prompt":"Write \\(3.7\\times10^{5}\\) in ordinary notation.","answer":"\\(370000\\)","solution":"A power of \\(10^{5}\\) moves the decimal point 5 places right.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":370000,"tolerance":0.000001}},{"id":"IBAI-1.1-P07","level":"Foundation","prompt":"Write \\(8.04\\times10^{-4}\\) in ordinary notation.","answer":"\\(0.000804\\)","solution":"A power of \\(10^{-4}\\) moves the decimal point 4 places left.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":0.0008039999999999999,"tolerance":5e-7}},{"id":"IBAI-1.1-P08","level":"Foundation","prompt":"Write \\(1.29\\times10^{7}\\) in ordinary notation.","answer":"\\(12900000\\)","solution":"A power of \\(10^{7}\\) moves the decimal point 7 places right.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":12900000,"tolerance":0.0000129}},{"id":"IBAI-1.1-P09","level":"Foundation","prompt":"Write \\(6.02\\times10^{-3}\\) in ordinary notation.","answer":"\\(0.00602\\)","solution":"A power of \\(10^{-3}\\) moves the decimal point 3 places left.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":0.006019999999999999,"tolerance":0.000005}},{"id":"IBAI-1.1-P10","level":"Foundation","prompt":"Write \\(9.9\\times10^{2}\\) in ordinary notation.","answer":"\\(990\\)","solution":"A power of \\(10^{2}\\) moves the decimal point 2 places right.","marks":2,"calculator":"Mental / GDC check","command":"Write","hint":"","tags":["standard form"],"check":{"mode":"number","value":990,"tolerance":0.000001}},{"id":"IBAI-1.1-P11","level":"Application","prompt":"Calculate \\((3.2\\times10^5)(4.5\\times10^{-3})\\).","answer":"\\(1.44\\times 10^{3}\\)","solution":"Multiply 3.2 by 4.5 and add exponents: \\(14.4\\times10^2=1.44\\times10^3\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":1440,"tolerance":0.000001}},{"id":"IBAI-1.1-P12","level":"Application","prompt":"Calculate \\(\\frac{7.5\\times10^8}{2.5\\times10^3}\\).","answer":"\\(3\\times 10^{5}\\)","solution":"Divide coefficients and subtract exponents: \\(3\\times10^5\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":300000,"tolerance":0.000001}},{"id":"IBAI-1.1-P13","level":"Application","prompt":"Calculate \\((6.0\\times10^{-7})(8.0\\times10^{11})\\).","answer":"\\(4.8\\times 10^{5}\\)","solution":"\\(48\\times10^4=4.8\\times10^5\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":480000,"tolerance":0.000001}},{"id":"IBAI-1.1-P14","level":"Application","prompt":"Calculate \\(\\frac{9.6\\times10^{-4}}{3.2\\times10^2}\\).","answer":"\\(3\\times 10^{-6}\\)","solution":"\\(9.6/3.2=3\\) and \\(-4-2=-6\\), giving \\(3\\times10^{-6}\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":0.000003,"tolerance":5e-7}},{"id":"IBAI-1.1-P15","level":"Application","prompt":"Calculate \\(4.7\\times10^6+8.5\\times10^5\\).","answer":"\\(5.55\\times 10^{6}\\)","solution":"Rewrite \\(8.5\\times10^5=0.85\\times10^6\\), then add coefficients.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":5550000,"tolerance":0.00000555}},{"id":"IBAI-1.1-P16","level":"Application","prompt":"Calculate \\(6.2\\times10^{-3}-7.5\\times10^{-4}\\).","answer":"\\(5.45\\times 10^{-3}\\)","solution":"Rewrite \\(7.5\\times10^{-4}=0.75\\times10^{-3}\\), giving \\(5.45\\times10^{-3}\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["operations"],"check":{"mode":"number","value":0.00545,"tolerance":0.000005}},{"id":"IBAI-1.1-P17","level":"Application","prompt":"A satellite transmits \\(2.4\\times10^6\\) bits each second for \\(3.5\\times10^3\\) seconds. Find the total number of bits.","answer":"\\(8.4\\times 10^{9}\\)","solution":"Multiply rate by time: \\(8.4\\times10^9\\) bits.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":8400000000,"tolerance":0.0084}},{"id":"IBAI-1.1-P18","level":"Application","prompt":"A bacterial sample contains \\(7.2\\times10^8\\) cells divided equally among \\(3.0\\times10^2\\) containers. Find the cells per container.","answer":"\\(2.4\\times 10^{6}\\)","solution":"Divide total cells by containers: \\(2.4\\times10^6\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":2400000,"tolerance":0.0000024}},{"id":"IBAI-1.1-P19","level":"Application","prompt":"A rectangular solar field is \\(1.8\\times10^3\\) m by \\(6.5\\times10^2\\) m. Find its area.","answer":"\\(1.17\\times 10^{6}\\)","solution":"Area is length × width: \\(11.7\\times10^5=1.17\\times10^6\\text{ m}^2\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":1170000,"tolerance":0.00000117}},{"id":"IBAI-1.1-P20","level":"Application","prompt":"A file has \\(4.0\\times10^7\\) records of \\(2.5\\times10^2\\) bytes each. Find the size in bytes.","answer":"\\(1\\times 10^{10}\\)","solution":"\\(4.0(2.5)\\times10^9=1.0\\times10^{10}\\) bytes.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":10000000000,"tolerance":0.01}},{"id":"IBAI-1.1-P21","level":"Reasoning","prompt":"Which quantity is greatest?","answer":"\\(7.9\\times10^6\\)","solution":"Compare exponents first. The only quantity with exponent 6 and coefficient 7.9 exceeds the other exponent-6 value.","marks":1,"calculator":"Mental","command":"Select","hint":"","tags":["reasoning"],"choices":["\\(8.2\\times10^5\\)","\\(7.9\\times10^6\\)","\\(9.1\\times10^4\\)","\\(1.2\\times10^6\\)"],"correct":1},{"id":"IBAI-1.1-P22","level":"Reasoning","prompt":"Which is closest to \\(10^{-4}\\)?","answer":"\\(1.2\\times10^{-4}\\)","solution":"\\(1.2\\times10^{-4}\\) has the same order of magnitude and coefficient near 1.","marks":1,"calculator":"Mental","command":"Select","hint":"","tags":["reasoning"],"choices":["\\(8.8\\times10^{-7}\\)","\\(1.2\\times10^{-4}\\)","\\(6.0\\times10^{-3}\\)","\\(9.0\\times10^{-2}\\)"],"correct":1},{"id":"IBAI-1.1-P23","level":"Reasoning","prompt":"The exponents of two positive quantities differ by 5. Their scale differs by approximately which factor?","answer":"\\(10^5\\)","solution":"A difference of 5 powers of ten corresponds to a factor of \\(10^5\\).","marks":1,"calculator":"Mental","command":"Select","hint":"","tags":["reasoning"],"choices":["5","10","\\(10^5\\)","\\(5^{10}\\)"],"correct":2},{"id":"IBAI-1.1-P24","level":"Reasoning","prompt":"Which expression is already in normalized standard form?","answer":"\\(7.2\\times10^7\\)","solution":"Only \\(7.2\\) lies between 1 and 10.","marks":1,"calculator":"Mental","command":"Select","hint":"","tags":["reasoning"],"choices":["\\(0.72\\times10^8\\)","\\(72\\times10^6\\)","\\(7.2\\times10^7\\)","\\(720\\times10^5\\)"],"correct":2},{"id":"IBAI-1.1-P25","level":"Reasoning","prompt":"Estimate \\(\\frac{6.2\\times10^7}{3.1\\times10^3}\\) using one significant figure, then state the exact standard-form value.","answer":"\\(2\\times 10^{4}\\)","solution":"Estimate \\(6/3\\times10^{4}=2\\times10^4\\). The exact quotient is also \\(2\\times10^4\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":20000,"tolerance":0.000001}},{"id":"IBAI-1.1-P26","level":"Reasoning","prompt":"A student writes \\(3.4\\times10^5+2.1\\times10^4=5.5\\times10^9\\). State the correct value.","answer":"\\(3.61\\times 10^{5}\\)","solution":"Use a common exponent: \\((3.4+0.21)\\times10^5=3.61\\times10^5\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":361000,"tolerance":0.000001}},{"id":"IBAI-1.1-P27","level":"Reasoning","prompt":"A population is \\(4.8\\times10^6\\), and a sample is \\(1.2\\times10^3\\). How many times larger is the population?","answer":"\\(4\\times 10^{3}\\)","solution":"Divide: \\((4.8/1.2)\\times10^{3}=4.0\\times10^3\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":4000,"tolerance":0.000001}},{"id":"IBAI-1.1-P28","level":"Reasoning","prompt":"A calculation gives \\(0.034\\times10^{-6}\\). Rewrite it in normalized standard form.","answer":"\\(3.4\\times 10^{-8}\\)","solution":"Move the decimal two places right and decrease the exponent by 2: \\(3.4\\times10^{-8}\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":3.4e-8,"tolerance":5e-10}},{"id":"IBAI-1.1-P29","level":"Reasoning","prompt":"Estimate \\((9.8\\times10^4)(2.1\\times10^{-6})\\) to one significant figure.","answer":"\\(0.2\\)","solution":"Use \\(10\\times2\\times10^{-2}=0.2\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":0.2,"tolerance":0.05}},{"id":"IBAI-1.1-P30","level":"Reasoning","prompt":"Two masses are \\(2.5\\times10^{-6}\\) kg and \\(7.5\\times10^{-9}\\) kg. Find their ratio.","answer":"\\(333.333333\\)","solution":"The ratio is \\((2.5/7.5)\\times10^3=\\frac13\\times10^3\\approx333\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reasoning"],"check":{"mode":"number","value":333.3333333333,"tolerance":0.5}},{"id":"IBAI-1.1-P31","level":"Challenge","prompt":"A cube has edge \\(3.2\\times10^{-3}\\) m. Find its volume in \\(\\text{m}^3\\).","answer":"\\(3.2768\\times 10^{-8}\\)","solution":"Cube the coefficient and multiply exponent by 3: \\(32.768\\times10^{-9}=3.2768\\times10^{-8}\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":3.2768000000000006e-8,"tolerance":5e-11}},{"id":"IBAI-1.1-P32","level":"Challenge","prompt":"Light travels at \\(3.00\\times10^8\\) m/s. Estimate the distance travelled in 2.5 days.","answer":"\\(6.48\\times 10^{13}\\)","solution":"Convert 2.5 days to 216000 s, then multiply to obtain \\(6.48\\times10^{13}\\) m.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":64800000000000,"tolerance":50000000000}},{"id":"IBAI-1.1-P33","level":"Challenge","prompt":"A country uses \\(4.2\\times10^{11}\\) kWh yearly for \\(3.5\\times10^7\\) people. Find annual kWh per person.","answer":"\\(1.2\\times 10^{4}\\)","solution":"Divide to get \\(1.2\\times10^4\\) kWh per person.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":12000,"tolerance":0.000001}},{"id":"IBAI-1.1-P34","level":"Challenge","prompt":"A sphere has radius \\(6.0\\times10^{-5}\\) m. Using \\(V=\\frac43\\pi r^3\\), find its volume.","answer":"\\(9.0478\\times 10^{-13}\\)","solution":"Substitute without prematurely rounding: \\(V\\approx9.05\\times10^{-13}\\text{ m}^3\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":9.047786842338604e-13,"tolerance":2.261946710584651e-13}},{"id":"IBAI-1.1-P35","level":"Challenge","prompt":"Convert \\(7.5\\times10^8\\) mm to kilometres.","answer":"\\(750\\)","solution":"There are \\(10^6\\) mm in 1 km, so the answer is \\(7.5\\times10^2=750\\) km.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":750,"tolerance":0.000001}},{"id":"IBAI-1.1-P36","level":"Challenge","prompt":"A sensor records \\(1.6\\times10^4\\) readings per second, each 24 bytes, for 30 days. Find the storage in bytes.","answer":"\\(9.9533\\times 10^{11}\\)","solution":"Multiply rate × bytes × seconds to get \\(9.95328\\times10^{11}\\) bytes.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":995328000000,"tolerance":2000000.995328}},{"id":"IBAI-1.1-P37","level":"Challenge","prompt":"A map uses scale \\(1:2.5\\times10^5\\). A route is \\(7.2\\times10^1\\) cm on the map. Find the real distance in km.","answer":"\\(180\\)","solution":"Real distance is \\(1.8\\times10^7\\) cm; divide by \\(10^5\\) cm/km to get 180 km.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":180,"tolerance":0.000001}},{"id":"IBAI-1.1-P38","level":"Challenge","prompt":"The density of a material is \\(7.8\\times10^3\\) kg/m³. Find the mass of \\(2.5\\times10^{-4}\\) m³.","answer":"\\(1.95\\)","solution":"Mass = density × volume = \\(1.95\\) kg.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":1.95,"tolerance":0.005}},{"id":"IBAI-1.1-P39","level":"Challenge","prompt":"A model estimates \\(6.4\\times10^9\\) events, each lasting \\(2.5\\times10^{-7}\\) s. Find total time in minutes.","answer":"\\(26.666667\\)","solution":"Total seconds are 1600; divide by 60 to obtain about 26.67 minutes.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":26.666666666666668,"tolerance":0.05}},{"id":"IBAI-1.1-P40","level":"Challenge","prompt":"Estimate the number of heartbeats in 80 years at 70 beats per minute. Give a standard-form estimate.","answer":"\\(2.9454\\times 10^{9}\\)","solution":"Multiply years × days × hours × minutes × beats to get about \\(2.95\\times10^9\\) beats.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","context"],"check":{"mode":"number","value":2945376000,"tolerance":24000.002945376}},{"id":"U1V3-1.1-P01","level":"Foundation","prompt":"Place \\(-3\\) in the smallest of the sets \\(\\mathbb N,\\mathbb Z,\\mathbb Q,\\mathbb R\\).","answer":"\\(\\mathbb Z\\)","solution":"−3 is an integer, and integers are also rational and real, but \\(\\mathbb Z\\) is the smallest listed set containing it.","hint":"Use the nesting \\(\\mathbb N\\subset\\mathbb Z\\subset\\mathbb Q\\subset\\mathbb R\\).","marks":1,"calculator":"No calculator","command":"State","choices":["\\(\\mathbb N\\)","\\(\\mathbb Z\\)","\\(\\mathbb Q\\)","\\(\\mathbb R\\)"],"correct":1},{"id":"U1V3-1.1-P02","level":"Foundation","prompt":"Write \\(0.0000729\\) in normalized scientific notation.","answer":"\\(7.29\\times10^{-5}\\)","solution":"Move the decimal five places right, so the exponent is −5.","hint":"The coefficient must satisfy \\(1\\le |a|<10\\).","marks":2,"calculator":"No calculator","command":"Calculate","check":{"mode":"text","accepted":["7.29x10^-5","7.29×10^-5","7.29e-5"]}},{"id":"U1V3-1.1-P03","level":"Foundation","prompt":"Write \\(4.06\\times10^5\\) in ordinary notation.","answer":"406000","solution":"Move the decimal point five places right.","hint":"A positive exponent makes the ordinary number larger.","marks":1,"calculator":"No calculator","command":"Calculate","check":{"mode":"number","value":406000,"tolerance":0.000001}},{"id":"U1V3-1.1-P04","level":"Application","prompt":"Calculate \\((6.4\\times10^7)(3.5\\times10^{-4})\\). Give the numerical value.","answer":"22400","solution":"Multiply coefficients: 6.4×3.5=22.4; add exponents: 7+(−4)=3. Thus 22.4×10^3=22400.","hint":"Estimate 6×4×10^3 first.","marks":2,"calculator":"No calculator","command":"Calculate","check":{"mode":"number","value":22400,"tolerance":0.000001}},{"id":"U1V3-1.1-P05","level":"Application","prompt":"Calculate \\(5.1\\times10^8-7.6\\times10^7\\).","answer":"\\(4.34\\times10^8\\)","solution":"Rewrite the second term as 0.76×10^8, then subtract coefficients.","hint":"Use a common power of ten before subtracting.","marks":2,"calculator":"No calculator","command":"Calculate","check":{"mode":"number","value":434000000,"tolerance":1}},{"id":"U1V3-1.1-P06","level":"Application","prompt":"A region has area \\(3.25\\times10^{-3}\\text{ km}^2\\). Convert the area to square metres.","answer":"3250 m²","solution":"Since 1 km²=10^6 m², multiply by 10^6: 3.25×10^3=3250.","hint":"Square the length conversion factor.","marks":2,"calculator":"No calculator","command":"Calculate","check":{"mode":"number","value":3250,"tolerance":0.000001}},{"id":"U1V3-1.1-P07","level":"Reasoning","prompt":"Which expression is not in normalized scientific notation?","answer":"\\(45.2\\times10^3\\)","solution":"Its coefficient has magnitude greater than 10. The other coefficients satisfy the normalization condition.","hint":"Check only the coefficient first.","marks":2,"calculator":"No calculator","command":"Identify","choices":["\\(4.52\\times10^4\\)","\\(-8.1\\times10^{-6}\\)","\\(45.2\\times10^3\\)","\\(1.00\\times10^0\\)"],"correct":2},{"id":"U1V3-1.1-P08","level":"Reasoning","prompt":"A calculator gives \\(1.91\\times10^{13}\\) for \\((5.8\\times10^7)(3.3\\times10^5)\\). Is the order of magnitude reasonable?","answer":"Yes","solution":"An estimate is 6×3×10^12=18×10^12=1.8×10^13, so the result has the correct scale.","hint":"Estimate coefficients to one significant figure.","marks":2,"calculator":"No calculator","command":"Evaluate","choices":["Yes, because the estimate is about \\(1.8\\times10^{13}\\)","No, it should be about \\(10^2\\)","No, it should be about \\(10^{12}\\) with coefficient below 1","It cannot be checked without exact multiplication"],"correct":0},{"id":"U1V3-1.1-P09","level":"Reasoning","prompt":"Explain why \\(3.140\\) and \\(\\pi\\) should not be described as the same exact number.","answer":"3.140 is a rational terminating decimal and an approximation to the irrational constant π.","solution":"A finite decimal has an exact rational value. It may approximate π to a stated precision, but it is not identical to π.","hint":"Distinguish representation from approximation.","marks":3,"calculator":"No calculator","command":"Explain"},{"id":"U1V3-1.1-P10","level":"Challenge","prompt":"A satellite stores 18 images. Each image has \\(2.40\\times10^8\\) pixels and each pixel uses \\(3.20\\times10^1\\) bits. Using 8 bits = 1 byte, find the total number of bytes.","answer":"\\(1.728\\times10^{10}\\) bytes","solution":"Total bits=18(2.40×10^8)(3.20×10^1)=1.3824×10^11. Divide by 8 to obtain 1.728×10^10 bytes.","hint":"Keep the factors separate until the final normalization.","marks":4,"calculator":"GDC allowed","command":"Calculate","check":{"mode":"number","value":17280000000,"tolerance":1}},{"id":"U1V3-1.1-P11","level":"Challenge","prompt":"A coating has dimensions \\(1.28\\times10^{-4}\\), \\(7.50\\times10^{-5}\\) and \\(2.40\\times10^{-6}\\) metres. Its density is \\(4.80\\times10^3\\text{ kg m}^{-3}\\). Find the total coating mass for \\(3.60\\times10^7\\) identical panels.","answer":"\\(3.98\\times10^{-3}\\) kg (3 s.f.)","solution":"Volume per panel=2.304e-14 m³. Multiply by density and panel count to obtain 0.003981312 kg, then round to 3 s.f.","hint":"Compute volume, then mass per panel, then total mass.","marks":5,"calculator":"GDC allowed","command":"Calculate","check":{"mode":"number","value":0.003981311999999999,"tolerance":0.000005}},{"id":"U1V3-1.1-P12","level":"Challenge","prompt":"A student enters \\(6.2\\times10^7\\div3.1\\times10^3\\) without brackets and reports \\(2.0\\times10^{11}\\). Diagnose the likely input error and give a reasonableness estimate for the intended calculation.","answer":"The intended result is about \\(2\\times10^4\\); the calculator likely interpreted the operations in a different order.","solution":"The intended expression is (6.2×10^7)/(3.1×10^3)=2×10^4. Parentheses around numerator and denominator make the structure explicit.","hint":"Compare exponent difference 7−3.","marks":4,"calculator":"GDC allowed","command":"Diagnose"}],"quiz":[{"id":"IBAI-1.1-Q01","level":"Quiz","prompt":"Write \\(0.0000912\\) in standard form.","answer":"\\(9.12\\times10^{-5}\\)","solution":"Move the decimal five places right.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"text","accepted":["9.12e-5","9.12*10^-5","9.12x10^-5"]}},{"id":"IBAI-1.1-Q02","level":"Quiz","prompt":"Write \\(6.07\\times10^4\\) in ordinary notation.","answer":"\\(60700\\)","solution":"Move four places right.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":60700,"tolerance":0.000001}},{"id":"IBAI-1.1-Q03","level":"Quiz","prompt":"Calculate \\((2.8\\times10^6)(3.0\\times10^{-4})\\).","answer":"\\(8.4\\times 10^{2}\\)","solution":"Multiply coefficients and add exponents.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":839.9999999999999,"tolerance":0.000001}},{"id":"IBAI-1.1-Q04","level":"Quiz","prompt":"Calculate \\(\\frac{5.4\\times10^9}{9.0\\times10^2}\\).","answer":"\\(6\\times 10^{6}\\)","solution":"Divide coefficients and subtract exponents.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":6000000,"tolerance":0.000006}},{"id":"IBAI-1.1-Q05","level":"Quiz","prompt":"Calculate \\(7.1\\times10^5+4.4\\times10^4\\).","answer":"\\(7.54\\times 10^{5}\\)","solution":"Rewrite the second term as \\(0.44\\times10^5\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":754000,"tolerance":0.000001}},{"id":"IBAI-1.1-Q06","level":"Quiz","prompt":"Which is larger: \\(8.9\\times10^{-3}\\) or \\(1.2\\times10^{-2}\\)? Enter 1 or 2.","answer":"2","solution":"The second has coefficient 1.2 at exponent −2, equal to 0.012.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":2,"tolerance":0.000001}},{"id":"IBAI-1.1-Q07","level":"Quiz","prompt":"A sensor takes \\(1.5\\times10^4\\) readings per second for one hour. Find the number of readings.","answer":"\\(5.4\\times 10^{7}\\)","solution":"Multiply by 3600 seconds.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":54000000,"tolerance":0.000054}},{"id":"IBAI-1.1-Q08","level":"Quiz","prompt":"A total of \\(4.8\\times10^{12}\\) units is shared equally among \\(1.6\\times10^7\\) groups. Find units per group.","answer":"\\(3\\times 10^{5}\\)","solution":"Divide to obtain \\(3.0\\times10^5\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":300000,"tolerance":0.000001}},{"id":"IBAI-1.1-Q09","level":"Quiz","prompt":"A square has side \\(2.2\\times10^{-3}\\) m. Find its area.","answer":"\\(4.84\\times 10^{-6}\\)","solution":"Square coefficient and exponent.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":0.00000484,"tolerance":5e-9}},{"id":"IBAI-1.1-Q10","level":"Quiz","prompt":"A process repeats \\(9.0\\times10^8\\) times at \\(2.4\\times10^{-6}\\) s each. Find total time in minutes.","answer":"\\(36\\)","solution":"Multiply to get seconds, then divide by 60.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":36,"tolerance":0.000001}},{"id":"U1V3-1.1-Q01","level":"Foundation","prompt":"Write \\(9.03\\times10^{-4}\\) in ordinary notation.","answer":"0.000903","solution":"Move the decimal four places left.","hint":"Negative exponent means a small value.","marks":1,"calculator":"No calculator","command":"Calculate","check":{"mode":"number","value":0.000903,"tolerance":1e-9}},{"id":"U1V3-1.1-Q02","level":"Application","prompt":"Calculate \\((2.7\\times10^{-6})/(9.0\\times10^2)\\).","answer":"\\(3.0\\times10^{-9}\\)","solution":"2.7/9=0.3 and 10^(−8), which normalizes to 3.0×10^−9.","hint":"Subtract exponents and normalize.","marks":2,"calculator":"No calculator","command":"Calculate","check":{"mode":"number","value":3e-9,"tolerance":1e-14}},{"id":"U1V3-1.1-Q03","level":"Reasoning","prompt":"Which is the best one-significant-figure estimate of \\((7.8\\times10^5)(4.1\\times10^{-2})\\)?","answer":"\\(3.2\\times10^4\\)","solution":"8×4×10^3=32×10^3=3.2×10^4.","hint":"Round coefficients, not exponents.","marks":2,"calculator":"No calculator","command":"Calculate","choices":["\\(3.2\\times10^3\\)","\\(3.2\\times10^4\\)","\\(3.2\\times10^7\\)","\\(3.2\\times10^{-7}\\)"],"correct":1},{"id":"U1V3-1.1-Q04","level":"Challenge","prompt":"A signal travels \\(1.44\\times10^{11}\\) m at \\(3.00\\times10^8\\text{ m s}^{-1}\\). Find the travel time in minutes.","answer":"8 minutes","solution":"Time=distance/speed=480 s=8 min.","hint":"Divide, then convert seconds to minutes.","marks":3,"calculator":"No calculator","command":"Calculate","check":{"mode":"number","value":8,"tolerance":0.000001}}],"exam":[{"id":"IBAI-1.1-E01","style":"Paper 1-style short response","title":"Solar data archive","calculator":"GDC expected","total_marks":8,"context":"A satellite stores \\(3.6\\times10^5\\) images. Each image requires \\(2.4\\times10^6\\) bytes.","parts":[{"label":"a","prompt":"Calculate the total storage in bytes, giving your answer in standard form.","marks":2,"answer":"\\(8.64\\times10^{11}\\) bytes","markscheme":"M1 multiplies the two quantities and applies exponent law; A1 normalized result."},{"label":"b","prompt":"A compression system reduces storage by 37%. Find the compressed storage in bytes in standard form.","marks":2,"answer":"\\(5.4432\\times10^{11}\\) bytes","markscheme":"M1 uses multiplier 0.63; A1 correct value."},{"label":"c","prompt":"The archive is copied at \\(1.5\\times10^8\\) bytes per second. Find the transfer time in minutes.","marks":3,"answer":"\\(60.48\\) minutes","markscheme":"M1 divides storage by rate; A1 seconds \\(3628.8\\); A1 converts to minutes."},{"label":"d","prompt":"State one reason the calculated time may differ from real transfer time.","marks":1,"answer":"Protocol overhead, variable transfer rate or interruptions.","markscheme":"A1 one relevant modelling limitation."}]},{"id":"IBAI-1.1-E02","style":"Paper 2-style extended response","title":"Water-use estimation","calculator":"GDC expected","total_marks":10,"context":"A campus has 1450 people. A preliminary model assumes each person uses \\(1.8\\times10^2\\) L of water per day on 210 operating days each year.","parts":[{"label":"a","prompt":"Estimate annual water use in litres and write it in standard form.","marks":3,"answer":"\\(5.481\\times10^7\\) L","markscheme":"M1 forms \\(1450(180)(210)\\); A1 evaluates; A1 standard form with units."},{"label":"b","prompt":"Convert the answer to cubic metres, using \\(1\\text{ m}^3=10^3\\text{ L}\\).","marks":2,"answer":"\\(5.481\\times10^4\\text{ m}^3\\)","markscheme":"M1 divides by \\(10^3\\); A1 correct standard form."},{"label":"c","prompt":"A conservation plan targets a 12% reduction. Calculate the target annual use in cubic metres.","marks":2,"answer":"\\(48\\,232.8\\text{ m}^3\\)","markscheme":"M1 uses multiplier 0.88; A1 correct value."},{"label":"d","prompt":"Give two assumptions that should be tested before using the model for budgeting.","marks":2,"answer":"Examples: equal use per person; exactly 210 days; no leakage/irrigation variation; stable population.","markscheme":"A1 each for two distinct assumptions."},{"label":"e","prompt":"Explain why reporting the target to the nearest litre would be misleading.","marks":1,"answer":"The assumptions and input estimates do not justify that precision.","markscheme":"A1 links reporting precision to model uncertainty."}]},{"id":"U1V3-1.1-EX","title":"Qatar satellite downlink","context":"A satellite sends 24 images. Each image contains 1.80×10^8 pixels, and each pixel is encoded using 2.40×10^1 bits.","parts":[{"label":"a","prompt":"Find the number of bits in one image, in normalized scientific notation.","marks":2,"answer":"4.32×10^9 bits","markscheme":"Multiply the coefficient and add exponents."},{"label":"b","prompt":"Using 8 bits = 1 byte, find the total data for all 24 images in bytes.","marks":3,"answer":"1.296×10^10 bytes","markscheme":"Multiply by 24 and divide by 8 without premature rounding."},{"label":"c","prompt":"The downlink rate is 1.60×10^7 bytes per second. Find the transmission time in minutes.","marks":3,"answer":"13.5 minutes","markscheme":"Time=data/rate=810 s=13.5 min."},{"label":"d","prompt":"Give one reason the actual transmission could take longer.","marks":2,"answer":"Protocol overhead, interruptions or retransmission","markscheme":"A valid contextual limitation earns credit."}],"style":"Paper 2 · scientific modelling","calculator":"GDC expected","total_marks":10}],"bankBridge":{"course":"ib-math-ai","unit":1,"lesson":"1.1","skillKeys":["IBAI.U1.NUMBER","IBAI.U1.MODELING"],"visibility":"authenticated-school-access","embeddedPrivatePrompts":false},"assessmentDesign":{"practiceLevels":{"Foundation":13,"Application":13,"Reasoning":13,"Challenge":13},"quizQuestions":14,"extendedTasks":3,"calculatorPolicy":"Technology is integrated throughout, with transparent setup and interpretation."},"referenceBasis":{"approach":"Original ECHS lesson adaptation informed by the supplied Pearson, Haese and Nikolaidis references.","sources":["Pearson — Number and algebra basics","Haese — Approximations and error","Nikolaidis — Numbers, rounding, scientific form and percentage error"],"courseVersion":"Current AI SL content, with transition awareness."},"v4Audit":{"unifiedContentSource":true,"slides":61,"practice":52,"quiz":14,"exam":3}};

